import { Config } from './packages/core/src/config/config.js';
import { debugLogger } from './packages/core/src/utils/debugLogger.js';
import path from 'node:path';

async function verifyTeams() {
  console.log('--- Starting Manual Verification ---');

  const config = new Config({
    sessionId: 'manual-verify-session',
    targetDir: process.cwd(),
    debugMode: true,
    model: 'gemini-1.5-flash',
    cwd: process.cwd(),
  });

  try {
    await config.initialize();

    const teamRegistry = config.getTeamRegistry();
    const teams = teamRegistry.getAllTeams();

    console.log(`Found ${teams.length} teams.`);

    for (const team of teams) {
      console.log(`- Team: ${team.name} (${team.displayName})`);
      console.log(`  Description: ${team.description}`);
      console.log(`  Agents: ${team.agents.map(a => a.name).join(', ')}`);
    }

    const manualTeam = teamRegistry.getTeam('manual-test-team');
    if (manualTeam && manualTeam.agents.some(a => a.name === 'manual-agent')) {
      console.log('\n✅ Verification Successful: Team and agent loaded correctly.');
    } else {
      console.error('\n❌ Verification Failed: Team or agent not found.');
      process.exit(1);
    }
  } catch (error) {
    console.error('\n❌ Verification Error:', error);
    process.exit(1);
  }
}

verifyTeams();

